CAT = "cusArith"; SEG = "ARI"
Q = [
 ('Goods have a customs value of ₦2,400,000 and attract import duty at 20%. How much is the duty?', '₦480,000', ['₦48,000', '₦120,000', '₦2,880,000'], '20% of ₦2,400,000 is 0.2 x 2,400,000 = ₦480,000. ₦2,880,000 is the value plus duty, not the duty.'),
 ('A consignment of 1,350 cartons arrives and 18% of them are damaged. How many cartons are undamaged?', '1,107 cartons', ['243 cartons', '1,332 cartons', '1,170 cartons'], '18% of 1,350 is 243 damaged, so 1,350 - 243 = 1,107 are undamaged. 243 is the damaged count.'),
 ('What is the simple interest on ₦75,000 at 6% per annum for 4 years?', '₦18,000', ['₦4,500', '₦13,500', '₦93,000'], 'Simple interest = PRT/100 = 75,000 x 6 x 4 / 100 = ₦18,000. ₦4,500 is one year only, and ₦93,000 is the amount, principal plus interest.'),
 ('A trader buys a standing fan for ₦6,400 and sells it for ₦7,520. What is the profit per cent?', '17.5%', ['14.9%', '11.2%', '15%'], 'Profit is ₦1,120, and profit per cent is taken on cost: 1,120 / 6,400 x 100 = 17.5%. Dividing by the selling price gives the wrong 14.9%.'),
 ('What is 2/5 + 3/8 in its simplest form?', '31/40', ['5/13', '6/40', '23/40'], 'Use the common denominator 40: 16/40 + 15/40 = 31/40. Adding tops and bottoms (5/13) is the classic error.'),
 ('What is 3 3/4 ÷ 1 1/2?', '2 1/2', ['5 5/8', '3 1/8', '2 1/4'], '15/4 ÷ 3/2 = 15/4 x 2/3 = 30/12 = 5/2 = 2 1/2. Multiplying instead of dividing gives 5 5/8.'),
 ('What is 0.36 x 0.25?', '0.09', ['0.9', '0.009', '0.61'], '36 x 25 = 900, and there are four decimal places in total, so 0.0900 = 0.09. 0.61 is the sum, not the product.'),
 ('A patrol team made 14, 19, 23, 11 and 18 arrests over five months. What is the mean number per month?', '17 arrests', ['18 arrests', '21.25 arrests', '16 arrests'], 'The total is 85 and 85 / 5 = 17. 18 is the median; 21.25 comes from dividing by 4.'),
 ('₦91,000 is shared between two officers in the ratio 3 : 4. What is the larger share?', '₦52,000', ['₦39,000', '₦30,333', '₦68,250'], 'There are 7 parts, so one part is ₦13,000 and the larger share is 4 x 13,000 = ₦52,000. ₦39,000 is the smaller share.'),
 ('A patrol van covers 252 km in 3 hours 30 minutes. What is its average speed?', '72 km/h', ['84 km/h', '76 km/h', '63 km/h'], '3 hours 30 minutes is 3.5 hours, and 252 / 3.5 = 72 km/h. Treating it as 3 hours gives 84 km/h.'),
 ("A night shift starts at 23:20 and lasts 8 hours 55 minutes. At what time does it end?",
 "08:15", ["07:15", "08:35", "09:15"],
 "23:20 plus 8 hours is 07:20, and 55 more minutes makes 08:15."),
 ('Seizures at a border post rose from 160 in one year to 212 the next. What is the percentage increase?', '32.5%', ['24.5%', '52%', '25%'], 'The increase is 52, and 52 / 160 x 100 = 32.5%. Dividing by the new figure (212) gives about 24.5%.'),
 ('If one unit of a foreign currency is worth ₦45, how many naira are 260 units worth?', '₦11,700', ['₦1,170', '₦117,000', '₦10,400'], '260 x 45 = 11,700, so ₦11,700. The other values come from a misplaced zero or using ₦40.'),
 ('A cooler marked ₦18,000 is sold at a 12.5% discount. What is the selling price?', '₦15,750', ['₦2,250', '₦15,500', '₦16,200'], '12.5% of 18,000 is 2,250, so the price is 18,000 - 2,250 = ₦15,750. ₦2,250 is the discount itself, and ₦16,200 would be a 10% discount.'),
 ("What is the LCM of 14, 24 and 40?",
 "840", ["1,680", "120", "13,440"],
 "14 = 2 x 7, 24 = 2³ x 3, 40 = 2³ x 5. The LCM takes each prime at its highest power: 2³ x 3 x 5 x 7 = 840. 13,440 is the product of all three, a common multiple but not the least."),
 ('What is the HCF of 112 and 168?', '56', ['28', '14', '336'], '112 = 2⁴ x 7 and 168 = 2³ x 3 x 7, so the HCF is 2³ x 7 = 56. 336 is the LCM.'),
 ('What is the square root of 3,481?', '59', ['57', '61', '69'], '59² = 60² - 2 x 60 + 1 = 3,600 - 120 + 1 = 3,481. 61² is 3,721, too large, and 57² is 3,249, too small.'),
 ('How is 63,500,000 written in standard form?', '6.35 x 10⁷', ['6.35 x 10⁶', '63.5 x 10⁶', '6.35 x 10⁸'], 'Move the decimal point 7 places to get a number between 1 and 10: 6.35 x 10⁷. 63.5 x 10⁶ is equal in value but not in standard form.'),
 ("What is 0.008461 rounded to two significant figures?",
 "0.0085", ["0.008", "0.0084", "0.00846"],
 "The first significant figure is 8 and the second is 4. The next digit, 6, rounds the 4 up, giving 0.0085. Leading zeros are not significant."),
 ('A bonded warehouse charges ₦1,250 per pallet per day. What is the charge for 16 pallets kept for 9 days?', '₦180,000', ['₦18,000', '₦1,800,000', '₦11,250'], '16 x 9 = 144 pallet-days, and 144 x 1,250 = ₦180,000. ₦11,250 is the charge for one pallet only.'),
 ('An excise duty of ₦35 per litre is charged on 2,400 litres of a drink. How much duty is due?', '₦84,000', ['₦8,400', '₦840,000', '₦72,000'], '2,400 x 35 = 84,000, so ₦84,000. ₦72,000 would be the duty at ₦30 per litre.'),
 ('What is 110011 in base two written in base ten?', '51', ['35', '49', '53'], '110011₂ = 32 + 16 + 2 + 1 = 51. Missing the 16s place gives 35.'),
 ('What does ₦60,000 amount to after 2 years at 10% per annum compound interest?', '₦72,600', ['₦72,000', '₦66,000', '₦12,600'], 'Year 1: 60,000 x 1.1 = 66,000. Year 2: 66,000 x 1.1 = 72,600. ₦72,000 is the simple interest amount; ₦12,600 is the interest only.'),
 ('Six officers can clear a backlog of files in 15 days. How long would nine officers take at the same rate?', '10 days', ['22.5 days', '12 days', '9 days'], 'The job is 6 x 15 = 90 officer-days, and 90 / 9 = 10 days. 22.5 days wrongly treats it as direct proportion.'),
 ('What percentage of 360 is 27?', '7.5%', ['13.3%', '75%', '27%'], '27 / 360 x 100 = 7.5%. 13.3% comes from 360 / 27, the wrong way round.'),
 ('A shipment weighs 3.6 tonnes. What is its mass in kilograms?', '3,600 kg', ['360 kg', '36,000 kg', '36 kg'], 'One tonne is 1,000 kg, so 3.6 tonnes is 3,600 kg.'),
 ('A rectangular inspection yard measures 48 m by 35 m. What is its area?', '1,680 m²', ['166 m²', '1,580 m²', '1,860 m²'], 'Area = 48 x 35 = 1,680 m². 166 m is the perimeter, not the area.'),
 ('A trader buys 40 bags of rice at ₦2,300 each and sells all of them for ₦86,480. What is the loss per cent?', '6%', ['6.4%', '5.5%', '8%'], 'Cost is 40 x 2,300 = ₦92,000, so the loss is ₦5,520 and 5,520 / 92,000 x 100 = 6%. Dividing by the selling price gives about 6.4%.'),
]
